package com.hrm.service;
import com.hrm.dto.OvertimeDTOs.*;
import com.hrm.security.AuthenticatedAccount;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class OvertimeSupplementService {
 private final JdbcTemplate db;private final OvertimeWorkspaceService workspace;private final OvertimeService core;private final OvertimePermissionService perms;private final Clock clock;private final int days;
 public OvertimeSupplementService(JdbcTemplate db,OvertimeWorkspaceService workspace,OvertimeService core,OvertimePermissionService perms,@Qualifier("hrmBusinessClock") Clock clock,@Value("${hrm.overtime.supplement-days:3}") int days){this.db=db;this.workspace=workspace;this.core=core;this.perms=perms;this.clock=clock;this.days=days;}
 public record Proposal(String expectedVersion,LocalDateTime start,LocalDateTime end,List<BreakInput> breaks,boolean noBreaksConfirmed,String reason){}
 public record Candidate(OvertimeWorkspaceService.Row row,boolean eligible,String unavailableReason,LocalDateTime deadline){}
 public record Page<T>(List<T> items,int page,int totalPages,long totalElements){}
 public record Request(long requestId,long overtimeId,long employeeId,String requestCode,String employeeLabel,String status,LocalDateTime start,LocalDateTime end,String reason,String sender,LocalDateTime submittedAt,String processor,LocalDateTime processedAt,String decisionReason,List<BreakInput> breaks,boolean canDecide){}
 private static void need(boolean ok,String why){if(!ok)throw new ResponseStatusException(HttpStatus.CONFLICT,why);}
 private static void reason(String value){if(value==null||value.isBlank()||value.length()>1000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Lý do bắt buộc, tối đa 1000 ký tự.");}
 private LocalDateTime now(){return LocalDateTime.now(clock);}
 private LocalDateTime deadline(OvertimeView o){return o.requestedEnd().toLocalDate().plusDays(days+1L).atStartOfDay().minusNanos(1);}
 private void writable(LocalDateTime start,LocalDateTime end){Long n=db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.payroll_periods p WITH(HOLDLOCK) JOIN dbo.payroll_batches b WITH(HOLDLOCK) ON b.period_id=p.period_id WHERE p.period_start<=? AND p.period_end>=? AND (b.locked_at IS NOT NULL OR b.published_at IS NOT NULL OR b.status='DA_CHOT')",Long.class,end.minusNanos(1).toLocalDate(),start.toLocalDate());need(n!=null&&n==0,"Kỳ công/lương đã khóa.");}
 private String unavailable(OvertimeView o){if(!"DA_DUYET".equals(o.status()))return "OT chưa được duyệt hoặc đã hủy.";if(o.confirmedBy()!=null)return "Giờ OT đã xác nhận.";if(o.actualStart()!=null&&o.actualEnd()!=null)return "OT đã đủ giờ vào/ra.";if(!now().isAfter(o.requestedEnd()))return "Chỉ bổ sung sau khi lịch OT kết thúc.";if(now().isAfter(deadline(o)))return "Đã hết hạn gửi bổ sung công OT ("+days+" ngày).";
  if(db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.ot_supplement_requests WHERE overtime_id=? AND status='CHO_XU_LY'",Long.class,o.overtimeId())>0)return "Đang có yêu cầu bổ sung chờ xử lý.";
  if(db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.overtime_request_details d JOIN dbo.employee_requests r ON r.request_id=d.request_id WHERE d.overtime_id=? AND r.status='CHO_DUYET'",Long.class,o.overtimeId())>0)return "Đang có yêu cầu OT khác chờ xử lý.";
  try{writable(o.requestedStart(),o.requestedEnd());}catch(ResponseStatusException e){return e.getReason();}return "";
 }
 public Page<Candidate> candidates(AuthenticatedAccount p,LocalDate from,LocalDate to,int page){perms.requireSelfRegistration(p);var result=workspace.search(p,new OvertimeWorkspaceService.Filter(true,from,to,null,null,"DA_DUYET",null,null,null,page));return new Page<>(result.items().stream().map(r->{String why=unavailable(r.ot());return new Candidate(r,why.isEmpty(),why,deadline(r.ot()));}).toList(),result.page(),result.totalPages(),result.totalElements());}
 private OvertimeView lock(AuthenticatedAccount p,long id){var o=core.get(p,id).request();db.query("SELECT employee_id FROM dbo.employees WITH(UPDLOCK,HOLDLOCK) WHERE employee_id=?",(rs,n)->rs.getLong(1),o.employeeId());db.query("SELECT overtime_id FROM dbo.overtime_requests WITH(UPDLOCK,HOLDLOCK) WHERE overtime_id=?",(rs,n)->rs.getLong(1),id);return core.get(p,id).request();}
 private byte[] version(long id){return db.queryForObject("SELECT row_version FROM dbo.overtime_requests WHERE overtime_id=?",byte[].class,id);}
 private void audit(long actor,long id,String action,String text){db.update("INSERT dbo.audit_logs(actor_account_id,action,target_table,target_record_key,reason) VALUES(?,?,'overtime_requests',?,?)",actor,action,Long.toString(id),text);}
 private List<BreakInput> validate(OvertimeView o,Proposal body){need(body!=null&&body.start()!=null&&body.end()!=null&&body.end().isAfter(body.start())&&!body.end().isAfter(now()),"Giờ vào/ra đề nghị không hợp lệ hoặc ở tương lai.");need(o.actualStart()==null||o.actualStart().equals(body.start()),"Giữ nguyên giờ check-in đã ghi nhận; yêu cầu này chỉ bổ sung giờ còn thiếu.");need(o.actualEnd()==null||o.actualEnd().equals(body.end()),"Giữ nguyên giờ ra đã ghi nhận.");need(body.breaks()!=null&&(!body.breaks().isEmpty()||body.noBreaksConfirmed()),"Nhập khoảng nghỉ thực tế hoặc xác nhận không nghỉ.");var rests=new ArrayList<>(body.breaks());need(rests.stream().allMatch(b->b!=null&&b.breakStart()!=null&&b.breakEnd()!=null),"Thiếu thời gian nghỉ.");rests.sort(Comparator.comparing(BreakInput::breakStart));var last=body.start();long minutes=0;for(var b:rests){need(!b.breakStart().isBefore(last)&&b.breakEnd().isAfter(b.breakStart())&&!b.breakEnd().isAfter(body.end()),"Khoảng nghỉ phải nằm trong giờ đề nghị và không chồng lấn.");minutes+=Duration.between(b.breakStart(),b.breakEnd()).toMinutes();last=b.breakEnd();}need(minutes<Duration.between(body.start(),body.end()).toMinutes(),"Giờ làm thực tế phải lớn hơn thời gian nghỉ.");writable(body.start(),body.end());return rests;}
 @Transactional("scheduleTransactionManager") public long submit(AuthenticatedAccount p,long id,Proposal body){var o=lock(p,id);var actor=perms.requireOwner(p,o.employeeId());reason(body==null?null:body.reason());need(unavailable(o).isEmpty(),unavailable(o));byte[] expected;try{expected=Base64.getDecoder().decode(body.expectedVersion());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Thiếu phiên bản OT.");}need(Arrays.equals(expected,version(id)),"OT đã thay đổi. Hãy tải lại.");var rests=validate(o,body);Long request=db.queryForObject("SET NOCOUNT ON; DECLARE @ids TABLE(id bigint); INSERT dbo.ot_supplement_requests(overtime_id,employee_id,parent_version,proposed_start,proposed_end,reason,created_by) OUTPUT INSERTED.request_id INTO @ids VALUES(?,?,?,?,?,?,?); SELECT id FROM @ids;",Long.class,id,o.employeeId(),expected,body.start(),body.end(),body.reason().trim(),actor.accountId());for(var b:rests)db.update("INSERT dbo.ot_supplement_breaks(request_id,break_start,break_end) VALUES(?,?,?)",request,b.breakStart(),b.breakEnd());audit(actor.accountId(),id,"OT_SUPPLEMENT_SUBMIT","Yêu cầu #"+request+": "+body.reason().trim());return request;}
 public Page<Request> list(AuthenticatedAccount p,boolean mine,LocalDate from,LocalDate to,int page){var actor=perms.active(p);if(mine)perms.requireSelfRegistration(p);else perms.requirePayrollRead(p);need(from!=null&&to!=null&&!to.isBefore(from)&&!to.isAfter(from.plusDays(366))&&page>=0,"Khoảng ngày hoặc phân trang không hợp lệ.");var ids=db.queryForList("SELECT r.request_id FROM dbo.ot_supplement_requests r JOIN dbo.overtime_requests o ON o.overtime_id=r.overtime_id WHERE CAST(o.requested_start AS date) BETWEEN ? AND ? ORDER BY r.submitted_at DESC,r.request_id DESC",Long.class,from,to);var rows=new ArrayList<Request>();for(long id:ids){try{var request=read(p,id);if(mine?Objects.equals(actor.employeeId(),request.employeeId()):!Objects.equals(actor.employeeId(),request.employeeId()))rows.add(request);}catch(ResponseStatusException e){if(e.getStatusCode()!=HttpStatus.FORBIDDEN&&e.getStatusCode()!=HttpStatus.NOT_FOUND)throw e;}}return new Page<>(rows.subList((int)Math.min(rows.size(),(long)page*20),(int)Math.min(rows.size(),((long)page+1)*20)),page,(rows.size()+19)/20,rows.size());}
 private List<BreakInput> breaks(long id){return db.query("SELECT break_start,break_end FROM dbo.ot_supplement_breaks WHERE request_id=? ORDER BY break_start",(rs,n)->new BreakInput(rs.getObject(1,LocalDateTime.class),rs.getObject(2,LocalDateTime.class)),id);}
 public Request read(AuthenticatedAccount p,long id){var rows=db.query("SELECT r.*,o.request_code,CONCAT(e.employee_code,N' - ',e.full_name) employee_label,s.username sender,d.username processor FROM dbo.ot_supplement_requests r JOIN dbo.overtime_requests o ON o.overtime_id=r.overtime_id JOIN dbo.employees e ON e.employee_id=r.employee_id JOIN dbo.accounts s ON s.account_id=r.created_by LEFT JOIN dbo.accounts d ON d.account_id=r.processed_by WHERE r.request_id=?",(rs,n)->new Request(rs.getLong("request_id"),rs.getLong("overtime_id"),rs.getLong("employee_id"),rs.getString("request_code"),rs.getString("employee_label"),rs.getString("status"),rs.getObject("proposed_start",LocalDateTime.class),rs.getObject("proposed_end",LocalDateTime.class),rs.getString("reason"),rs.getString("sender"),rs.getObject("submitted_at",LocalDateTime.class),rs.getString("processor"),rs.getObject("processed_at",LocalDateTime.class),rs.getString("decision_reason"),List.of(),false),id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy yêu cầu bổ sung OT.");var r=rows.get(0);var o=core.get(p,r.overtimeId()).request();boolean can=false;try{perms.requireOperate(p,o.employeeId(),o.requestedStart().toLocalDate());can=r.status().equals("CHO_XU_LY");}catch(ResponseStatusException e){if(e.getStatusCode()!=HttpStatus.FORBIDDEN)throw e;}return new Request(r.requestId(),r.overtimeId(),r.employeeId(),r.requestCode(),r.employeeLabel(),r.status(),r.start(),r.end(),r.reason(),r.sender(),r.submittedAt(),r.processor(),r.processedAt(),r.decisionReason(),breaks(id),can);}
 @Transactional("scheduleTransactionManager") public void decide(AuthenticatedAccount p,long request,boolean approve,String decisionReason){reason(decisionReason);var r=read(p,request);var o=lock(p,r.overtimeId());var actor=perms.requireOperate(p,o.employeeId(),o.requestedStart().toLocalDate());db.query("SELECT request_id FROM dbo.ot_supplement_requests WITH(UPDLOCK,HOLDLOCK) WHERE request_id=?",(rs,n)->rs.getLong(1),request);r=read(p,request);need(r.canDecide(),"Yêu cầu đã xử lý hoặc không đủ quyền độc lập.");if(approve){byte[] original=db.queryForObject("SELECT parent_version FROM dbo.ot_supplement_requests WHERE request_id=?",byte[].class,request);need(Arrays.equals(original,version(o.overtimeId())),"Công OT đã thay đổi từ khi gửi yêu cầu.");need("DA_DUYET".equals(o.status())&&o.confirmedBy()==null,"Trạng thái OT không còn phù hợp.");var proposal=new Proposal(null,r.start(),r.end(),r.breaks(),r.breaks().isEmpty(),r.reason());var rests=validate(o,proposal);long regular=db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.attendance_records WITH(HOLDLOCK) WHERE employee_id=? AND invalidated_at IS NULL AND actual_start<? AND (actual_end IS NULL OR actual_end>?)",Long.class,o.employeeId(),r.end(),r.start());long other=db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.overtime_requests WITH(HOLDLOCK) WHERE employee_id=? AND overtime_id<>? AND status='DA_DUYET' AND actual_start<? AND (actual_end IS NULL OR actual_end>?)",Long.class,o.employeeId(),o.overtimeId(),r.end(),r.start());need(regular==0&&other==0,"Giờ đề nghị chồng lấn công khác.");db.update("UPDATE dbo.ot_supplement_requests SET status='DA_CHAP_NHAN',processed_by=?,processed_at=SYSUTCDATETIME(),decision_reason=? WHERE request_id=?",actor.accountId(),decisionReason.trim(),request);int minutes=(int)rests.stream().map(b->Duration.between(b.breakStart(),b.breakEnd())).reduce(Duration.ZERO,Duration::plus).toMinutes();core.recordActual(p,o.overtimeId(),new Actual(r.start(),r.end(),minutes,rests,"Duyệt bổ sung OT #"+request+": "+decisionReason.trim()));}else{db.update("UPDATE dbo.ot_supplement_requests SET status='TU_CHOI',processed_by=?,processed_at=SYSUTCDATETIME(),decision_reason=? WHERE request_id=?",actor.accountId(),decisionReason.trim(),request);}audit(actor.accountId(),o.overtimeId(),approve?"OT_SUPPLEMENT_APPROVE":"OT_SUPPLEMENT_REJECT","Yêu cầu #"+request+": "+decisionReason.trim());}
}
